import { AndroidPermission } from '@droid/android';
import { useTranslation } from '@fanfanlo';
import { Button } from '@mui/material';
import { useState } from 'react';
import { AndroidPermissionsPopup } from './AndroidPermissionsPopup';

// 日志前缀
const LOG_PREFIX = '[AndroidPermissionsButton]';

interface IPermissionsProps {
  permissions: AndroidPermission[];
}

interface AndroidPermissionsButtonProps {
  permissionsProps: IPermissionsProps; // 权限数据对象
}

/**
 * 权限选择器按钮组件
 * 点击按钮时弹出权限选择器弹窗
 */
export const AndroidPermissionsButton: React.FC<AndroidPermissionsButtonProps> = ({
  permissionsProps
}) => {
  // console.log(`${LOG_PREFIX} 组件初始化`);
// C:\work\android-droid\html\website-2024-12\apps\homepage\src\components\permissions\android-permissions\AndroidPermissionsButton.tsx
  const { t } = useTranslation('droid-ui/components/permissions/android-permissions/content');
  const [open, setOpen] = useState(false);
  const handleOpen = () => {
    // console.log(`${LOG_PREFIX} 按钮被点击, 准备打开弹窗`);
    setOpen(true);
    // console.log(`${LOG_PREFIX} 弹窗状态已设置为 true`);
  };

  const handleClose = () => {
    // console.log(`${LOG_PREFIX} 准备关闭弹窗`);
    setOpen(false);
    // console.log(`${LOG_PREFIX} 弹窗状态已设置为 false`);
  };

  return (
    <>
      <Button variant="contained" onClick={handleOpen} data-testid="AndroidPermissionsButton__selectButton__01JG2B0095" data-test-comment="Android权限选择按钮，点击后打开权限选择弹窗">
        {t('AndroidPermissionsButton.ButtonLabel')}
      </Button>
      <AndroidPermissionsPopup
        open={open}
        onClose={handleClose}
        permissionsProps={permissionsProps}
      />
    </>
  );
};
